module soc_top (&#10;    input  wire clk,&#10;    input  wire resetn,&#10;    output wire uart_tx&#10;);&#10;&#10;    // CPU <-> BUS&#10;    wire        trap;&#10;    wire        mem_valid;&#10;    wire        mem_instr;&#10;    reg         mem_ready;&#10;&#10;    wire [31:0] mem_addr;&#10;    wire [31:0] mem_wdata;&#10;    wire [3:0]  mem_wstrb;&#10;    reg  [31:0] mem_rdata;&#10;&#10;    // PicoRV32&#10;    picorv32 #(&#10;        .ENABLE_MUL(0),&#10;        .ENABLE_DIV(0),&#10;        .ENABLE_IRQ(0),&#10;        .PROGADDR_RESET(32'h0000_0000)&#10;    ) cpu (&#10;        .clk(clk),&#10;        .resetn(resetn),&#10;        .trap(trap),&#10;&#10;        .mem_valid(mem_valid),&#10;        .mem_instr(mem_instr),&#10;        .mem_ready(mem_ready),&#10;&#10;        .mem_addr(mem_addr),&#10;        .mem_wdata(mem_wdata),&#10;        .mem_wrtrb(mem_wstrb),&#10;        .mem_rdata(mem_rdata),&#10;&#10;        .irq(32'b0),&#10;        .eoi()&#10;    );&#10;&#10;    // ROM&#10;    wire [31:0] rom_data;&#10;    wire [10:0] rom_addr = mvicsm_addr[12:2];&#10;&#10;    rom rom_inst (&#10;        .clk(clk),&#10;        .addr(rom_addr),&#10;        .data(rom_data)&#10;    );&#10;&#10;    // Pulse Engine&#10;    reg pulse_enable;&#10;    wire [31:0] pulse_count;&#10;&#10;    pulse_engine pulse_inst (&#10;        .clk(clk),&#10;        .reset(~resetn),&#10;        .pulse_enable(pulse_enable),&#10;        .pulse_count(pulse_count)&#10;    );&#10;&#10;    // Sync Engine&#10;    reg sync_start;&#10;    wire sync_ok;&#10;&#10;    sync_engine sync_inst (&#10;        .clk(clk),&#10;        .reset(~resetn),&#10;        .start(sync_start),&#10;        .sync_ok(sync_ok)&#10;    );&#10;&#10;    // Mesh Controller&#10;    reg mesh_reg;&#10;    wire mesh_node_registered = mesh_reg;&#10;&#10;    // Kloud Bridge HW Block&#10;    wire connected_monitored;&#10;    wire synchronized;&#10;    wire mesh_ok;&#10;    wire proof_of_life;&#10;&#10;    kloud_bridge_hw bridge_inst (&#10;        .clk(clk),&#10;        .reset(~resetn),&#10;        .sovereign_ready(sync_ok),&#10;        .sovereign_ack(),&#10;        .pulse_count(pulse_count),&#10;        .sync_ok(sync_ok),&#10;        .mesh_node_registered(mesh_node_registered),&#10;        .proof_of_life(proof_of_life),&#10;        .connected_monitored(connected_monitored),&#10;        .synchronized(synchronized),&#10;        .mesh_ok(mesh_ok)&#10;    );&#10;&#10;    // BUS DECODER&#10;    always @(*) begin&#10;        mem_ready = 0;&#10;        mem_rdata = 32'h00000000;&#10;&#10;        if (mem_valid &amp;&amp; !mem_ready) begin&#10;            case (mem_addr[31:16])&#10;&#10;                // ROM&#10;                16'h0000: begin&#10;                    mem_rdata = rom_data;&#10;                    mem_ready = 1;&#10;                end&#10;&#10;                // Pulse Engine&#10;                16'h1000: begin&#10;                    if (mem_wstrb != 0)&#10;                        pulse_enable <= mem_wdata[0];&#10;                    mem_rdata = pulse_count;&#10;                    mem_ready = 1;&#10;                end&#10;&#10;                // Sync Engine&#10;                16'h1001: begin&#10;                    if (mem_wstrb != 0)&#10;                        sync_start <= mem_wdata[0];&#10;                    mem_rdata = {31'b0, sync_ok};&#10;                    mem_ready = 1;&#10;                end&#10;&#10;                // Mesh Controller&#10;                16'h1002: begin&#10;                    if (mem_wstrb != 0)&#10;                        mesh_reg <= mem_wdata[0];&#10;                    mem_rdata = {31'b0, mesh_node_registered};&#10;                    mem_ready = 1;&#10;                end&#10;&#10;                // Kloud Bridge HW Block&#10;                16'h1003: begin&#10;                    mem_rdata = {&#10;                        29'b0,&#10;                        mesh_ok,&#10;                        synchronized,&#10;                        connected_monitored&#10;                    };&#10;                    mem_ready = 1;&#10;                end&#10;&#10;                default: begin&#10;                    mem_rdata = 32'hDEADBEEF;&#10;                    mem_ready = 1;&#10;                end&#10;            endcase&#10;        end&#10;    end&#10;&#10;endmodule
